-- Pictures: 1-3 small PNGs each; the first becomes the profile picture ----------------------
ON CONFLICT DO NOTHING;

UPDATE users SET profile_picture_id = p.id
FROM user_pictures p
WHERE p.id = ('00000000-0000-4000-9000-' || substring(users.id::text from 25))::uuid
  AND users.profile_picture_id IS NULL AND users.email LIKE '%@glancesync.test';

